}

func (s DocState) memento() DocState {    // value copy + explicit clone
	s.Tags = slices.Clone(s.Tags)         // shallow: clone nested refs too
	return s
}

type Editor struct { state DocState; history []DocState }   // caretaker

func snapshot(s DocState) ([]byte, error) {
	var buf bytes.Buffer
	if err := gob.NewEncoder(&buf).Encode(s); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil              // detached, persistable memento
}

func restore(data []byte) (DocState, error) {
	var s DocState
	err := gob.NewDecoder(bytes.NewReader(data)).Decode(&s)
	return s, err
}
